<?php $address=json_decode((string)$order['address_json'],true)?:[]; ?><div class="commerce-order-layout"><div><section class="card"><div class="card-heading"><div><p class="section-kicker">Order <?= e($order['order_number']) ?></p><h2><?= e($order['customer_name']) ?></h2><p class="card-subtitle">Placed <?= e($order['placed_at']) ?> · <?= e(ucfirst($order['fulfillment_method'])) ?></p></div><span class="badge <?= $order['payment_status']==='paid'?'ok':'warn' ?>"><?= e(ucfirst($order['payment_status'])) ?></span></div><div class="table-scroll"><table><thead><tr><th>Item</th><th>SKU</th><th>Qty</th><th>Unit</th><th>Total</th></tr></thead><tbody><?php foreach($order['items'] as $i): ?><tr><td><strong><?= e($i['name']) ?></strong></td><td><?= e($i['sku']) ?></td><td><?= (int)$i['quantity'] ?></td><td>$<?= number_format((int)$i['unit_price_minor']/100,2) ?></td><td><strong>$<?= number_format((int)$i['line_total_minor']/100,2) ?></strong></td></tr><?php endforeach; ?></tbody><tfoot><tr><th colspan="4">Order total</th><th><?= e($order['currency']) ?> $<?= number_format((int)$order['total_minor']/100,2) ?></th></tr></tfoot></table></div></section><section class="card"><h2>Customer and fulfillment</h2><dl class="commerce-detail-list"><div><dt>Email</dt><dd><a href="mailto:<?= e_attr($order['customer_email']) ?>"><?= e($order['customer_email']) ?></a></dd></div><div><dt>Phone</dt><dd><?= e($order['customer_phone']?:'Not provided') ?></dd></div><div><dt>Address</dt><dd><?= e(implode(', ',array_filter($address))) ?: 'Not required' ?></dd></div><div><dt>Customer notes</dt><dd><?= nl2br(e($order['customer_notes']?:'None')) ?></dd></div></dl></section></div><aside class="card"><p class="section-kicker">Workflow</p><h2>Update order</h2><?php if($order['status']==='cancelled'): ?><div class="inline-notice"><strong>Order cancelled</strong><span>Tracked inventory was restored. Cancelled orders cannot be reopened.</span></div><?php endif; ?><form method="post" class="checkout-form"><?= $csrf->field() ?><label>Order status<select name="status"><?php foreach(['new','confirmed','preparing','ready','completed','cancelled'] as $s): ?><option value="<?= e_attr($s) ?>" <?= $order['status']===$s?'selected':'' ?> <?= $order['status']==='cancelled'&&$s!=='cancelled'?'disabled':'' ?>><?= e(ucfirst($s)) ?></option><?php endforeach; ?></select></label><label>Payment status<select name="payment_status"><?php foreach(['pending','paid','refunded','void'] as $s): ?><option value="<?= e_attr($s) ?>" <?= $order['payment_status']===$s?'selected':'' ?>><?= e(ucfirst($s)) ?></option><?php endforeach; ?></select></label><label>Payment reference<input name="payment_reference" maxlength="190" value="<?= e_attr($order['payment_reference']??'') ?>" placeholder="Transaction note or confirmation"></label><label>Internal notes<textarea name="internal_notes" rows="6" maxlength="3000"><?= e($order['internal_notes']??'') ?></textarea></label><button class="btn">Save order</button></form></aside></div>
